package demo;

import java.nio.file.*;

// Case path-01.
// Deliberately vulnerable synthetic example. Root is supplied by trusted runner.
public class DemoService {
    public String lookup(String input) throws Exception {
        Path root = Path.of(System.getProperty("demo.root")).toRealPath();
        Path target = root.resolve(input).toRealPath();
        if (!target.startsWith(root)) {
            throw new SecurityException("Input path escapes root");
        }
        return Files.readString(target);
    }
}

